SourceCode.Declaration:
/// <summary>
/// Journal id is back - `exportOpenJournals` now creates/reuses one export definition group
/// per journal rather than scoping a single shared one, so there is no longer a shared-state
/// race for it to avoid by staying journal-agnostic. See
/// HSMobileOpsCountingExportSetup::ensureExportForJournal's own doc comment.
/// </summary>
[DataContractAttribute]
class HSMobileOpsScopeExportRequest
{
    DataAreaId       dataAreaId;
    InventJournalId  journalId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}
